int32_t MulFixed32High(int32_t a, int32_t b)
{
    int64_t result = static_cast<int64_t>(a) * static_cast<int64_t>(b);
    int32_t high = static_cast<int32_t>(result >> 32);
    return static_cast<int32_t>(static_cast<uint32_t>(high) << 1);
}

static int CompareKeys(const int32_t* a, const int32_t* b)
{
    if (a[0] != b[0]) return a[0] - b[0];
    if (a[1] != b[1]) return a[1] - b[1];
    return a[2] - b[2];
}

struct CallbackNode {
    CallbackNode* next;
    void (*callback)(void*, void*);
    void* param1;
    void* param2;
};

static void TraverseAndCollect(CallbackNode** listHead, const CommandNode* node, const int32_t* key)
{
    if (node == nullptr) return;
    TraverseAndCollect(listHead, node->left, key);
    if (CompareKeys(node->key, key) == 0) {
        CallbackNode* newNode = static_cast<CallbackNode*>(malloc(sizeof(CallbackNode)));
        newNode->next = nullptr;
        newNode->callback = node->callback;
        newNode->param1 = node->param1;
        newNode->param2 = node->param2;
        *listHead = newNode;
        listHead = &newNode->next;
    }
    TraverseAndCollect(listHead, node->right, key);
}

extern CommandNode* g_commandTreeRoot;

void ConsoleSlotUpdate();

void DispatchCommand(int32_t* key, void* context1, void* context2)
{
    if (g_commandTreeRoot == nullptr) return;

    CommandNode* node = g_commandTreeRoot;
    while (node != nullptr) {
        int cmp = CompareKeys(key, node->key);
        if (cmp < 0) {
            node = node->left;
        } else if (cmp > 0) {
            node = node->right;
        } else {
            break;
        }
    }

    if (node != nullptr) {
        CallbackNode* callbackList = nullptr;
        CallbackNode** listTail = &callbackList;
        TraverseAndCollect(listTail, g_commandTreeRoot, key);

        CallbackNode* current = callbackList;
        while (current != nullptr) {
            if (current->callback) {
                current->callback(current->param1, current->param2);
            }
            current = current->next;
        }

        current = callbackList;
        while (current != nullptr) {
            CallbackNode* next = current->next;
            free(current);
            current = next;
        }

        ConsoleSlotUpdate();
    }
}

ConsoleSlot g_consoleSlots[MAX_CONSOLE_SLOTS] = {};
uint8_t g_gameMode = 0;

void FormatAndDisplayText(const ConsoleDisplayEntry* entry, int withSound)
{
    if (entry == nullptr) return;

    char expanded[2048] = {};
    const char* srcStr = nullptr;

    if (entry->flags < 0) {
        srcStr = entry->stringPtr;
    } else {
        srcStr = entry->stringPtr;
    }

    if (srcStr) {
        StringExpand(reinterpret_cast<uint8_t*>(expanded), reinterpret_cast<const uint8_t*>(srcStr));
    }

    (void)withSound;
}

void DisplayWithSound(const ConsoleDisplayEntry* entry)
{
    if (g_gameMode == 0x2C) return;

    if (entry && entry->flags >= 0) {
        SoundPlaySample(0x16, 63, 256);
    }

    FormatAndDisplayText(entry, 1);
}

void EventPreprocess(const ConsoleDisplayEntry* entry)
{
    if (g_gameMode != 4) {
        SysMenuPlayTime();
    }
    DisplayWithSound(entry);
}

void DisplayTextEntry(const ConsoleDisplayEntry* entry)
{
    if (entry == nullptr) return;

    ConsoleDisplayEntry local;
    memcpy(&local, entry, sizeof(ConsoleDisplayEntry));
    local.flags = -1;

    FormatAndDisplayText(&local, 0);
}

void ConsoleSlotUpdate()
{
    while (true) {
        int maxState = 0;
        int maxIdx = 0;

        for (int i = 0; i < MAX_CONSOLE_SLOTS; i++) {
            if (maxState < g_consoleSlots[i].state) {
                maxState = g_consoleSlots[i].state;
                maxIdx = i;
            }
        }

        if (maxState < 4) break;

        ConsoleSlot* slot = &g_consoleSlots[maxIdx];

        if (maxState == 4) {
            FinalizeConsoleSlot(slot);
        } else if (maxState == 5) {
            slot->state = 6;
        } else if (maxState == 6) {
            if (slot->allocatedMem) {
                free(slot->allocatedMem);
                slot->allocatedMem = nullptr;
            }
            slot->state = 0;
        } else {
            break;
        }
    }
}

int CompareKeysExtended(const int32_t* a, const int32_t* b)
{
    if (a[0] != b[0]) return a[0] - b[0];
    if (a[1] != b[1]) return a[1] - b[1];
    if (a[2] != b[2]) return a[2] - b[2];
    if (a[3] != b[3]) return a[3] - b[3];
    if (a[4] != b[4]) return a[4] - b[4];
    return a[5] - b[5];
}

void RegisterCommandHandler(int32_t key1, int32_t key2, int32_t key3,
                           int32_t extra1, int32_t extra2, int32_t extra3)
{
    CommandNodeExtended* node = static_cast<CommandNodeExtended*>(malloc(sizeof(CommandNodeExtended)));
    if (!node) return;
    
    node->left = nullptr;
    node->right = nullptr;
    node->key[0] = key1;
    node->key[1] = key2;
    node->key[2] = key3;
    node->extraKey1 = extra1;
    node->extraKey2 = extra2;
    node->extraKey3 = extra3;
    
    CommandNode** treePtr = &g_commandTreeRoot;
    while (*treePtr != nullptr) {
        int32_t nodeKey[3] = {(*treePtr)->key[0], (*treePtr)->key[1], (*treePtr)->key[2]};
        int32_t newKey[3] = {key1, key2, key3};
        int cmp = CompareKeys(newKey, nodeKey);
        if (cmp < 0) {
            treePtr = &(*treePtr)->left;
        } else {
            treePtr = &(*treePtr)->right;
        }
    }
    *treePtr = reinterpret_cast<CommandNode*>(node);
}

void UnregisterCommandHandler(int32_t key1, int32_t key2, int32_t key3,
                             int32_t extra1, int32_t extra2, int32_t extra3)
{
    [[maybe_unused]] int32_t searchKey[6] = {key1, key2, key3, extra1, extra2, extra3};
    CommandNode** treePtr = &g_commandTreeRoot;
    
    while (*treePtr != nullptr) {
        int32_t nodeKey[3] = {(*treePtr)->key[0], (*treePtr)->key[1], (*treePtr)->key[2]};
        int32_t cmpKey[3] = {key1, key2, key3};
        int cmp = CompareKeys(cmpKey, nodeKey);
        
        if (cmp < 0) {
            treePtr = &(*treePtr)->left;
        } else if (cmp > 0) {
            treePtr = &(*treePtr)->right;
        } else {
            CommandNode* found = *treePtr;
            CommandNode* left = found->left;
            CommandNode* right = found->right;
            
            if (right == nullptr) {
                *treePtr = left;
                free(found);
            } else if (left == nullptr) {
                *treePtr = right;
                free(found);
            } else {
                CommandNode* successor = right;
                while (successor->left != nullptr) {
                    successor = successor->left;
                }
                successor->left = left;
                *treePtr = right;
                free(found);
            }
            break;
        }
    }
}

void ProcessBytecodeInstruction(int** ip, ConsoleSlot* slot,
                               void (*callback)(int32_t, int32_t, int32_t, void*, ConsoleSlot*, int32_t),
                               int32_t instructionIndex)
{
    if (!ip || !*ip || !slot || !callback) return;
    
    uint8_t opcode = **reinterpret_cast<uint8_t**>(ip);
    *reinterpret_cast<uint8_t**>(ip) += 1;
    
    int32_t opcodeId = opcode;
    int32_t param1 = 0;
    int32_t param2 = 0;
    
    callback(opcodeId, param1, param2, nullptr, slot, instructionIndex);
}

void SetupBytecodeContext(ConsoleSlot* slot,
                         void (*callback)(int32_t, int32_t, int32_t, void*, ConsoleSlot*, int32_t))
{
    if (!slot || !callback || !slot->bytecodePtr) return;
    
    int* ip = static_cast<int*>(slot->bytecodePtr);
    int instructionCount = 0;
    
    for (int i = 0; i < instructionCount; i++) {
        ProcessBytecodeInstruction(&ip, slot, callback, i);
    }
}

void FinalizeConsoleSlot(ConsoleSlot* slot)
{
    if (!slot) return;
    
    slot->state = 3;
    
    if (slot->bytecodePtr != nullptr) {
        SetupBytecodeContext(slot, [](int32_t opcode, int32_t p1, int32_t p2, 
                                      void* ctx, ConsoleSlot* s, int32_t idx) {
            UnregisterCommandHandler(opcode, p1, p2, 0, 0, idx);
        });
        slot->bytecodePtr = nullptr;
        slot->bytecodePos = -1;
    }
    
    if (slot->missionData) {
        int* ip = static_cast<int*>(slot->missionData);
        RunBytecode(ip, nullptr);
    }
    
    if (slot->state == 3) {
        if (slot->missionData) {
            slot->bytecodePtr = slot->missionData;
            slot->bytecodePos = slot->bytecodeEnd;
            
            SetupBytecodeContext(slot, [](int32_t opcode, int32_t p1, int32_t p2,
                                          void* ctx, ConsoleSlot* s, int32_t idx) {
                RegisterCommandHandler(opcode, p1, p2, 0, 0, idx);
            });
        }
        slot->state = 1;
    }
}

uint32_t BC_Read32(uint8_t** ip)
{
    if (!ip || !*ip) return 0;
    
    uint8_t* ptr = *ip;
    uint32_t value = ptr[0] | (ptr[1] << 8) | (ptr[2] << 16) | (ptr[3] << 24);
    *ip = ptr + 4;
    return value;
}

uint32_t BC_ReadGameState(uint32_t index)
{
    switch (index) {
    case 0: return 0;
    case 1: return 0;
    case 2: return 0;
    case 3: return 0;
    case 4: return 0;
    case 5: case 6: case 7: case 8: case 9: case 10: case 11:
        return 0;
    case 12: return 0;
    case 13: return 0;
    case 14: return g_gameMode;
    case 15: return 0;
    case 16: return 0;
    case 17: return 0;
    case 18: return 0;
    case 19: return 0;
    case 20: return 0;
    default: return 0;
    }
}

