int32_t IterateObjects(void* objects, int32_t (*callback)(void*))
{
    if (!objects || !callback) return 0;
    
    int32_t result = 0;
    int32_t count = 0;
    void** ptr = static_cast<void**>(objects);
    
    while (*ptr != nullptr) {
        result += callback(ptr + count * 0x11);
        count++;
        ptr = static_cast<void**>(objects) + count * 0x11;
    }
    
    return result;
}

int32_t FindObject(void* objects, int32_t (*callback)(void*), int32_t maxCount)
{
    if (!objects || !callback) return 0;
    
    int32_t count = 0;
    void** ptr = static_cast<void**>(objects);
    bool found = false;
    
    while (*ptr != nullptr) {
        int32_t result = callback(ptr + count * 0x11);
        if (result != 0 && maxCount == 0) {
            found = true;
            break;
        }
        if (result != 0) {
            maxCount--;
        }
        count++;
        ptr = static_cast<void**>(objects) + count * 0x11;
    }
    
    return found ? count : 0;
}

int32_t FindObjectReverse(void* base, int32_t (*callback)(int32_t), int32_t param)
{
    if (!base || !callback) return 0;
    
    int32_t index = 0x72;
    uint8_t* basePtr = static_cast<uint8_t*>(base);
    uint8_t* ptr = basePtr + 0x72;
    int32_t* ptr2 = reinterpret_cast<int32_t*>(basePtr + 0x9798);
    
    while (*ptr == 0 || callback(index * 0x152 + 0x74) == 0 || *ptr2 != param) {
        index--;
        ptr2--;
        ptr--;
        if (index < 1) {
            return index;
        }
    }
    
    return index;
}

bool IsObjectFlagSet(void* obj)
{
    if (!obj) return false;
    uint8_t* ptr = static_cast<uint8_t*>(obj);
    return (ptr[0x14c] & 0x10) != 0;
}

bool IsObjectTypeValid(void* obj)
{
    if (!obj) return false;
    uint32_t* ptr = static_cast<uint32_t*>(obj);
    uint32_t type = ptr[0x82 / 4];
    return type >= 0x76 && type <= 0x85;
}

bool IsObjectTypeValid2(void* obj)
{
    if (!obj) return false;
    uint16_t* ptr = static_cast<uint16_t*>(obj);
    uint16_t type = ptr[0xc / 2];
    return type >= 0x76 && type <= 0x85;
}

void BC_ExecuteCallback(int32_t* state, int32_t param)
{
    if (!state) return;
    
    if (*state == 1 && param < state[2]) {
        int32_t value = state[2 + param];
        int32_t result = BC_ReadExpression(reinterpret_cast<int**>(&value), static_cast<intptr_t>(state[0]));
        if (result != 0) {
            *state = 2;
            RunBytecode(reinterpret_cast<int*>(&value), nullptr);
            if (*state == 2) {
                *state = 1;
            }
        }
    }
}

void CommandTreeFreeRecursive(CommandNode* node)
{
    if (!node) return;
    
    CommandTreeFreeRecursive(node->left);
    CommandTreeFreeRecursive(node->right);
    free(node);
}

void CommandTreeClearAll()
{
    CommandTreeFreeRecursive(g_commandTreeRoot);
    g_commandTreeRoot = nullptr;
}

void ConsoleSetupButton(const ConsoleDisplayEntry* state)
{
    ConsoleDisplayEntry localState;
    memcpy(&localState, state, sizeof(ConsoleDisplayEntry));
    localState.flags = static_cast<int32_t>(0xFFFFFFFF);
}

void UpdateDisplayFromMission(ConsoleDisplayEntry* entry)
{
    if (!entry) return;
    
    entry->param2 = *reinterpret_cast<const int32_t*>(entry->stringPtr);
    entry->stringCode = 0x992d;
    DisplayTextEntry(entry);
}

void ResetConsoleState()
{
    SetGameStateValue(0, 2);
    SetGameStateValue(0, 0);
    ResetConsoleInternals();
}

void AddToConsoleQueue(const int32_t* entry)
{
    if (!entry) return;
    
    static int32_t g_consoleQueue[45 * 12] = {};
    static int g_queueCount = 0;
    
    if (g_queueCount < 45) {
        int32_t* dest = &g_consoleQueue[g_queueCount * 12];
        for (int i = 0; i < 12; i++) {
            dest[i] = entry[i];
        }
        g_queueCount++;
    }
}

void SetAndAddToQueue(int32_t value, int32_t* entry)
{
    if (!entry) return;
    
    entry[0] = value;
    AddToConsoleQueue(entry);
}

