void SetGameStateValue(int32_t index, int32_t value)
{
    // R1230/R1231: JJFFE_SCRIPTVAR_WRITES=1 logs index==54 stores (frame, value,
    // top-3 raw return addresses). Names via dladdr need -rdynamic; print RAs.
    static const bool s_scriptVarWrites = [] {
        const char* e = std::getenv("JJFFE_SCRIPTVAR_WRITES");
        return e && e[0] != '\0' && e[0] != '0';
    }();
    if (s_scriptVarWrites && index == 54) {
        void* ra0 = __builtin_return_address(0);
        void* ra1 = __builtin_return_address(1);
        void* ra2 = __builtin_return_address(2);
        std::fprintf(stderr,
                     "SCRIPTVAR_WRITE frame=%u index=%d value=%d ra=%p,%p,%p\n",
                     g_replayFrame, index, value, ra0, ra1, ra2);
    }
    if (index >= 0 && index < static_cast<int32_t>(std::size(s_scriptVars))) {
        s_scriptVars[index] = static_cast<uint32_t>(value);
    }
    FUNC_000048(2, 0, index);
}

