// Mission string table: the ASM DATA_004682 holds the offsets of the packed
// mission string block (DATA_004683); the blob's copy of the table is
// zero-filled, so rebuild it by walking the block (verified against the ASM:
// 196="1st Encounter", 197="Turner Class", 198="   FIRST\nENCOUNTERS").
static uint32_t g_missionStrOff[256] = {};
static int g_missionStrCount = 0;
static void EnsureMissionStringTable()
{
    if (g_missionStrCount != 0) return;
    const uint8_t* blob = data::GetDataBlob();
    if (!blob) return;
    const uint8_t* p = blob + data::OFFSET_DATA_004683;
    int n = 0;
    while (n < 256) {
        // block end: a run of 3+ zero bytes
        if (p[0] == 0 && p[1] == 0 && p[2] == 0) break;
        g_missionStrOff[n++] = static_cast<uint32_t>(p - blob);
        const uint8_t* end = reinterpret_cast<const uint8_t*>(
            strchr(reinterpret_cast<const char*>(p), 0));
        if (!end) break;
        p = end + 1;
    }
    g_missionStrCount = n;
    if (getenv("AB_GLYPH_DEBUG"))
        fprintf(stderr, "MSTR table: %d strings (196=%s)\n", n,
                n > 196 && g_missionStrOff[196] + blob
                    ? reinterpret_cast<const char*>(blob + g_missionStrOff[196])
                    : "?");
}

// FUNC_001345_StringExpandFF40Code — real: id = code & 0x3fff → mission
// string table → StringExpand (ffe.asm:4ee2b).
static uint8_t* FUNC_001345_StringExpandFF40Code(uint8_t* dst, uint32_t code)
{
    const uint8_t* blob = data::GetDataBlob();
    if (blob) {
        EnsureMissionStringTable();
        const uint32_t id = code & 0x3fff;
        if (id < static_cast<uint32_t>(g_missionStrCount)) {
            StringExpand(dst, blob + g_missionStrOff[id]);
        } else {
            *dst = 0;
        }
    } else {
        *dst = 0;
    }
    return dst + strlen(reinterpret_cast<const char*>(dst));
}

