// Console slot pool (150 slots, 36 bytes each = 9 int32s per slot)
static int32_t g_consoleSlotPool[150 * 9] = {};  // DATA_008561

// FUNC_000038 - Update slot state
void UpdateSlotState(uint32_t slotIndex)
{
    if (slotIndex >= 150) return;
    
    int32_t* slot = &g_consoleSlotPool[slotIndex * 9];
    
    // Check if slot is active and in valid state
    if (slot[0] > 0 && slot[0] < 5) {
        // Check if slot has pending unregister
        if (slot[2] != 0) {
            // Would call UnregisterCommandHandler
            slot[2] = 0;
            slot[3] = -1;
        }
        
        // Check if slot should be finalized
        if (slot[4] >= 0) {
            slot[0] = 5;  // Mark for finalization
        } else {
            // Increment position counter (stored in upper 16 bits of slot[0])
            int16_t counter = static_cast<int16_t>(slot[0] >> 16);
            counter++;
            slot[0] = (slot[0] & 0xFFFF) | (static_cast<int32_t>(counter) << 16);
            slot[0] = (slot[0] & 0xFFFF) | (6 << 16);  // Set state to 6
        }
    }
}

