// FUNC_000051 - Allocate console slot from pool
void* AllocateConsoleSlot(int32_t missionIndex, int32_t param)
{
    if (missionIndex < 0 || missionIndex >= 150) return nullptr;
    
    // Find free slot (state == 0)
    for (int i = 0; i < 150; i++) {
        int32_t* slot = &g_consoleSlotPool[i * 9];
        if (slot[0] == 0) {
            // Initialize slot
            slot[0] = 4;  // State = allocated
            *reinterpret_cast<int16_t*>(&slot[1]) = static_cast<int16_t>(i);
            int16_t counter = *reinterpret_cast<int16_t*>(&slot[1]);
            counter++;
            *reinterpret_cast<int16_t*>(&slot[1]) = counter;
            slot[2] = 0;
            slot[3] = -1;
            slot[4] = 0;
            slot[5] = -1;
            slot[6] = missionIndex;
            
            // Get mission data pointer from table (stub - would use real data blob)
            int32_t missionData = 0;  // Would be: *reinterpret_cast<int32_t*>(0x1697 + missionIndex * 4);
            slot[7] = missionData;
            
            // Allocate memory for slot data
            int32_t size = 256;  // Default size, would be: *reinterpret_cast<int32_t*>(missionData + 0x10) << 2;
            void* allocated = malloc(size);
            *reinterpret_cast<void**>(&slot[8]) = allocated;
            
            if (allocated) {
                *reinterpret_cast<int32_t*>(allocated) = slot[1];
                *reinterpret_cast<int32_t*>(static_cast<uint8_t*>(allocated) + 4) = param;
            }
            
            return slot;
        }
    }
    
    return nullptr;  // No free slots
}

