// FUNC_000043 - CompareKeys32: Compare 3 int32 keys
int32_t CompareKeys32(const int32_t* a, const int32_t* b)
{
    if (!a || !b) return 0;
    
    if (a[0] != b[0]) {
        return a[0] - b[0];
    }
    if (a[1] != b[1]) {
        return a[1] - b[1];
    }
    return a[2] - b[2];
}

// FUNC_000046 - CollectMatchingCallbacks: Recursive tree walker
void CollectMatchingCallbacks(void** listHead, void* treeNode, const int32_t* key)
{
    if (!listHead || !treeNode) return;
    
    // Tree node structure: [left, right, key1, key2, key3, extra1, extra2, extra3]
    int32_t* node = static_cast<int32_t*>(treeNode);
    
    // Recurse left
    if (node[0] != 0) {
        CollectMatchingCallbacks(listHead, reinterpret_cast<void*>(node[0]), key);
    }
    
    // Check if keys match
    int32_t cmp = CompareKeys32(node + 2, key);
    if (cmp == 0) {
        // Allocate new list node
        void* newNode = malloc(0x10);
        if (newNode) {
            int32_t* listNode = static_cast<int32_t*>(newNode);
            listNode[0] = 0;  // next = null
            listNode[1] = node[5];  // copy extra fields
            listNode[2] = node[6];
            listNode[3] = node[7];
            
            // Insert at head
            *reinterpret_cast<void**>(*listHead) = newNode;
            *listHead = newNode;
        }
    }
    
    // Recurse right
    if (node[1] != 0) {
        CollectMatchingCallbacks(listHead, reinterpret_cast<void*>(node[1]), key);
    }
}

