// FUNC_000063 - StringCompareCaseInsensitive: Case-insensitive string comparison
int32_t StringCompareCaseInsensitive(const char* a, const char* b)
{
    if (!a || !b) return a ? 1 : (b ? -1 : 0);
    
    while (*a != '\0') {
        int ca = tolower(static_cast<unsigned char>(*a));
        int cb = tolower(static_cast<unsigned char>(*b));
        if (ca != cb) break;
        a++;
        b++;
    }
    
    int ca = tolower(static_cast<unsigned char>(*a));
    int cb = tolower(static_cast<unsigned char>(*b));
    return ca - cb;
}

