// FUNC_000122 - BufferedFileRead: Refills read buffer from FILE*
size_t BufferedFileRead(BufferedFileStream* stream)
{
    if (!stream || !stream->file) {
        return (size_t)-1;
    }

    size_t bytesRead;
    if (stream->bufferSize < 0x2000) {
        bytesRead = fread(stream->buffer, 1, stream->bufferSize, stream->file);
        stream->bytesRead = stream->bufferSize;
        stream->bufferSize = 0;
    } else {
        bytesRead = fread(stream->buffer, 1, 0x2000, stream->file);
        stream->bufferSize -= 0x2000;
        stream->bytesRead = 0x2000;
    }
    stream->bufferPos = 0;
    return bytesRead;
}

// FUNC_000123 - BufferedFileReadBytes: Reads N bytes from buffered stream
size_t BufferedFileReadBytes(BufferedFileStream* stream, void* dest, size_t count)
{
    if (!stream || !dest) return 0;

    if ((int)count < stream->bytesRead - stream->bufferPos) {
        memcpy(dest, stream->buffer + stream->bufferPos, count);
        stream->bufferPos += count;
        return count;
    } else {
        int remaining = stream->bytesRead - stream->bufferPos;
        memcpy(dest, stream->buffer + stream->bufferPos, remaining);
        stream->bufferPos += remaining;

        BufferedFileRead(stream);
        return BufferedFileReadBytes(stream, (uint8_t*)dest + remaining, count - remaining);
    }
}

// FUNC_000124 - BufferedFileSkip: Skips N bytes in buffered stream
void BufferedFileSkip(BufferedFileStream* stream, size_t count)
{
    if (!stream) return;

    int available = stream->bytesRead - stream->bufferPos;
    if (available < (int)count) {
        count -= available;
        stream->bufferPos = stream->bytesRead;
        BufferedFileRead(stream);
        BufferedFileSkip(stream, count);
    } else {
        stream->bufferPos += count;
    }
}

