    int8_t skipSlot = 0;
    const int mode = MissionViewScratchBuild(obj, q31Orig, d, &skipSlot, nullptr);
    auto i32 = [&](int off) -> int32_t& {
        return *reinterpret_cast<int32_t*>(obj + off);
    };
    const uint8_t* player = reinterpret_cast<const uint8_t*>(static_cast<uintptr_t>(DATA_008861));
    const int32_t px = *reinterpret_cast<const int32_t*>(player + 0x3e);
    const int32_t py = *reinterpret_cast<const int32_t*>(player + 0x46);
    const int32_t pz = *reinterpret_cast<const int32_t*>(player + 0x4e);
    const int32_t dx = d[0], dy = d[1], dz = d[2];

    // Read back the camera basis as 16.16 rows (right, up, forward) - the
    // scale the port's Camera3D rotation uses - and the position delta the
    // ASM added to the scratch object. For the rear view the negation is
    // applied here at 16.16 from the pre-negation basis, so it is exact and
    // not rounded twice through the Q31 shift.
