    FUNC_000585(static_cast<int>(obj), static_cast<int>(dt), 0, static_cast<int>(dt));

    // 6. Transpose back into the scaffold's 16.16 scale. The +0x4000 rounding
    //    makes an untouched matrix round-trip exactly (1.0 saturates to
    //    0x7fffffff going in, and comes back as 0x10000 rather than 0xffff).
    for (int r = 0; r < 3; ++r)
        for (int c = 0; c < 3; ++c)
            rot9[3 * c + r] = (mtx[3 * r + c] + 0x4000) >> 15;
