// FUNC_001346_StringExpandFF80Code (ffe.asm:84111): [DATA_009149] = vars, then
// DATA_007649[(code >> 9) & 0x3f](code & 0x1ff, vars, dst); returns its cursor.
uint8_t* FUNC_001346_StringExpandFF80Code(uint8_t* dst, uint32_t code, intptr_t vars)
{
    DATA_009149[0] = vars;
    const uint32_t index = (code >> 9) & 0x3f;
    // g_ff80Expand leaves slot 0 (ff80) null for FUNC_001343's stray-code callers;
    // here the code is always the caller's own.
    const intptr_t fn = index == 0 ? reinterpret_cast<intptr_t>(&FUNC_000895)
                                   : index < 21 ? g_ff80Expand[index] : 0;
    if (!fn) {
        *dst = 0;
        return dst;
    }
    return reinterpret_cast<uint8_t*>(reinterpret_cast<intptr_t (*)(uint32_t, intptr_t, uint8_t*)>(fn)(
        code & 0x1ff, DATA_009149[0], dst));
}

