// The call oracle's write of a render context's object word (ctx+0x14c): the key
// StoreCtxObjPtr hands out, where the ASM stores the object's address.
uint32_t OracleCtxObjKey(std::uintptr_t obj)
{
    return StoreCtxObjPtr(reinterpret_cast<const void*>(obj));
}

// The same for a vertex bank (ctx+0x150, StoreCtxBankPtr), and the bank a key
// stands for.
uint32_t OracleCtxBankKey(std::uintptr_t bank)
{
    return StoreCtxBankPtr(reinterpret_cast<const void*>(bank));
}

std::uintptr_t OracleCtxBankPtr(uint32_t key)
{
    const auto it = g_ctxBankPtrs.find(key);
    return it == g_ctxBankPtrs.end() ? 0 : reinterpret_cast<std::uintptr_t>(it->second);
}

// The call oracle's view of a job-list link: the port stores an arena offset where
// the ASM stores the node's address (FUNC_001778, ffe.asm:111941-111946).
std::uintptr_t OracleJobLinkPtr(uint32_t link)
{
    return reinterpret_cast<std::uintptr_t>(JobOffToPtr(link));
}

